            if (queryRequestJson.LensOption.IsSet && queryRequestJson.Lens == null)
                throw new ArgumentNullException(nameof(queryRequestJson.Lens), "Property is required for class QueryRequestJson.");

            writer.WriteString("query", queryRequestJson.Query);

            if (queryRequestJson.DecomposeQueryOption.IsSet)
                if (queryRequestJson.DecomposeQueryOption.Value != null)
                    writer.WriteBoolean("decomposeQuery", queryRequestJson.DecomposeQueryOption.Value.Value);
                else
                    writer.WriteNull("decomposeQuery");

            if (queryRequestJson.ExpandGraphOption.IsSet)
                writer.WriteBoolean("expandGraph", queryRequestJson.ExpandGraphOption.Value.Value);

            if (queryRequestJson.FilterOption.IsSet)
                if (queryRequestJson.FilterOption.Value != null)
                {
                    writer.WritePropertyName("filter");
                    JsonSerializer.Serialize(writer, queryRequestJson.Filter, jsonSerializerOptions);
                }
                else
                    writer.WriteNull("filter");
            if (queryRequestJson.GraphAlphaOption.IsSet)
                writer.WriteNumber("graphAlpha", queryRequestJson.GraphAlphaOption.Value.Value);

            if (queryRequestJson.GraphDepthOption.IsSet)
                writer.WriteNumber("graphDepth", queryRequestJson.GraphDepthOption.Value.Value);

            if (queryRequestJson.GraphEdgesOption.IsSet)
            {
                writer.WritePropertyName("graphEdges");
                JsonSerializer.Serialize(writer, queryRequestJson.GraphEdges, jsonSerializerOptions);
            }
            if (queryRequestJson.KOption.IsSet)
                writer.WriteNumber("k", queryRequestJson.KOption.Value.Value);

            if (queryRequestJson.LensOption.IsSet)
            {
                writer.WritePropertyName("lens");
                JsonSerializer.Serialize(writer, queryRequestJson.Lens, jsonSerializerOptions);
            }
            if (queryRequestJson.LocationOption.IsSet)
                if (queryRequestJson.LocationOption.Value != null)
                {
                    writer.WritePropertyName("location");
                    JsonSerializer.Serialize(writer, queryRequestJson.Location, jsonSerializerOptions);
                }
                else
                    writer.WriteNull("location");
            if (queryRequestJson.ModeOption.IsSet)
            {
                var modeRawValue = QueryModeValueConverter.ToJsonValue(queryRequestJson.Mode.Value);
                writer.WriteString("mode", modeRawValue);
            }
            if (queryRequestJson.RrfKOption.IsSet)
                writer.WriteNumber("rrfK", queryRequestJson.RrfKOption.Value.Value);

            if (queryRequestJson.ThresholdOption.IsSet)
                writer.WriteNumber("threshold", queryRequestJson.ThresholdOption.Value.Value);

            if (queryRequestJson.UseHydeOption.IsSet)
                if (queryRequestJson.UseHydeOption.Value != null)
                    writer.WriteBoolean("useHyde", queryRequestJson.UseHydeOption.Value.Value);
                else
                    writer.WriteNull("useHyde");

            if (queryRequestJson.UseRerankerOption.IsSet)
                if (queryRequestJson.UseRerankerOption.Value != null)
                    writer.WriteBoolean("useReranker", queryRequestJson.UseRerankerOption.Value.Value);
                else
                    writer.WriteNull("useReranker");

            if (queryRequestJson.VectorWeightOption.IsSet)
                writer.WriteNumber("vectorWeight", queryRequestJson.VectorWeightOption.Value.Value);
        }
    }
